// === Tab: mySketch ===
//Lesson: Create a nested loop, making a cool pattern with it. Maybe try to animate?
var offs = 0;
var offs2 = 0;
var offs3 = 0;
var offs4 = 0;
var chn = 0;
let lapse = 0;    // mouse timer

function setup() {
    //createCanvas(600, 950);
	  createCanvas(1112, 834);
	  colorMode(HSB, 255);
    background(0);
}

function draw() {
    //background(0);
	  fill(0, 20);
	  noStroke();
	  rect(0, 0, width, height);
    for (let cx = 0; cx <= 11; cx += PI / 6) {
        //fill(127, cx * 30, 127);
        for (let cy = 65; cy <= 600; cy += 35) {
            fill(cx * 12 + offs2, 200, 255); //- cx * 10 + offs4);
            if (cy % 2 === 0) {
                chn = -1;
                fill(255 - cx * 8 + offs4, 200, 255); // - cy / 3 + offs2);
            } else {
                chn = 1;
                fill(cx * 15 + offs4, 200, 255); //- cy / 3 + offs2);
            }
            ellipse(width / 2 + cos(cx + offs * chn) * cy, height / 2 + sin(cx + offs * chn) * cy, height / 30);
        }
    }
    offs = millis() / 2000;
    offs2 = sin(millis() / 2000) * 30;
    offs3 = sin(millis() / 1900) * 30;
    offs4 = sin(millis() / 1800) * 30;
}

function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 500){
    save('pix.jpg');
    lapse = millis();
  } 
}

